/// <summary>
/// CB626_TMSEngineSOPackingSlip
/// Class responsible for the TSIG TOT calculation (with CCR)
/// </summary>
final class METTMSShipmentItemGroupUOM_TOTCCR extends METTMSShipmentItemGroupUOM_TOT
{
}

Method.Source:
void initParameters(METTMSEngineSalesOrderProccessLinesTmp _processLinesTmp,
                    METTMSEngineSalesOrderProccessLinesTmp _lineTmpSum,
                    METTMSShipmentOrderIdentifier          _tmsShipmentOrderIdentifier,
                    InventLocationId                       _headerInventLocationId,
                    boolean                                _isToteCustomer,
                    Set                                    _ccrToteIds,
                    SalesId                                _salesId,
                    WMSPickingRouteId                      _pickingRouteId,
                    boolean                                _isKegItem = false)
{
    super(_processLinesTmp, _lineTmpSum, _tmsShipmentOrderIdentifier, _headerInventLocationId, _isToteCustomer, _ccrToteIds, _salesId, _pickingRouteId, _isKegItem);

    this.initCCRParameters();
}

/// <summary>
/// Method to calculate TSIG volume (cube)
/// </summary>
/// <param name = "_quantity">TSIG quantity</param>
/// <returns>TSIG volume (cube)</returns>
METWHSPalletVolume cube(METQty _quantity)
{
    // Add Sum of (CCRWhs_ToteVolume * CCR_RepackContainersByCommodity for this CCR_LineCommodity) from all supplying warehouses
    return super(_quantity) + sumRepackContainersByCommodityToteVolumeCCR;
}

/// <summary>
/// Method to calculate TSIG quantity
/// </summary>
/// <returns>TSIG quantity</returns>
METQty quantity()
{
    // Add Count(CCR_RepackContainersByCommodity for this CCR_LineCommodity
    return super() + sumRepackContainersByCommodityQtyCCR;
}

/// <summary>
/// Method to calculate TSIG weight
/// </summary>
/// <param name = "_quantity">TSIG quantity</param>
/// <returns>TSIG weight</returns>
METWHSPalletWeight weight(METQty _quantity)
{
    // Add Sum of (CCRWhs_ToteWeight * CCR_RepackContainersByCommodity for this CCR_LineCommodity) from all supplying warehouses
    return super(_quantity) + sumRepackContainersByCommodityToteWeightCCR;
}
